item.command:
"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$RX = '"'P=true|("'^|[|;])true[|]|PID=host|IPC=host|USERNS=host|SYS_ADMIN|SYS_PTRACE|SYS_MODULE|SYS_BOOT|DAC_READ_SEARCH|DAC_OVERRIDE|'"\\[ALL\\]|unconfined|/run/docker\\.sock|containerd\\.sock|crio\\.sock|(M=|"'^|[|;])/->|(M=|''^|[|;])/(etc|root|proc|sys|boot|var/lib/docker)->|(M=|''^|[|;])/etc/(shadow|gshadow|sudoers)'"'

"'$cases = @(
  @{ d='"'docker root source first (pipe format)';    s='false|/->/host;';                    want='OPEN'  },
  @{ d='docker root alternate destination';          s='false|/->/mnt/host;';               want='OPEN'  },
  @{ d='docker benign tmp source';                   s='false|/tmp->/host;';                want='CLEAN' },
  @{ d='docker socket bind';                         s='false|/var/run/docker.sock->/x;';   want='OPEN'  },
  @{ d='docker privileged (pipe format)';            s='true|/tmp->/x;';                    want='OPEN'  },
  @{ d='docker root source middle';                  s='false|/tmp->/x;/->/host;/var->/v;'; want='OPEN'  },
  @{ d='docker root source last';                    s='false|/tmp->/x;/var->/v;/->/host;'; want='OPEN'  }
)

foreach ("'$c in $cases) {
  $got = if ($c.s -match $RX) { '"'OPEN' } else { 'CLEAN' }
  "'$status = if ($got -eq $c.want) { '"'PASS' } else { 'REDO' }
  Write-Host \""'$status | $($c.d) | got=$got want=$($c.want)"
}'

